// Extract JSON from AI response
const aiText = $input.item.json.content[0].text;
const jsonMatch = aiText.match(/\{[\s\S]*\}/);
const structured = jsonMatch ? JSON.parse(jsonMatch[0]) : {};

const auditData = {
  source: $('02 Merge Sources').item.json.source,
  company_name: $('02 Merge Sources').item.json.company.name,
  contact_email: $('02 Merge Sources').item.json.contact.email,
  structured_audit: structured,
  raw_responses: $('02 Merge Sources').item.json.raw_responses
};

return { json: auditData };

// Log completion
return [{
  json: {
    workflow: 'wf-03-audit',
    run_id: $execution.id,
    level: 'info',
    message: `Audit created for ${$('04 Extract JSON').item.json.company_name}`,
    payload: {
      audit_id: $input.item.json.id,
      company_id: $input.item.json.company_id
    }
  }
}];
